# DK KHP.  København H - Hellerup
#
let kh = path("d3.dk.khp");

with detail = 3, railway = :first :double :pax :removed {
    with link = "line.dk.KHP" {
        track(:station, kh[:kob.yl, :nor.yf]);
        track(kh[:nor.yf, :nor - 0.49sw]);
    }

    with link = "point.dk.Nørrebro-gammel", railway = :station {
        track(kh[:nor - 0.5sw, :nor + 0.5sw]);
        marker(:right :de.bf, kh[:nor] >> 0.5mo >> 0.5mt);
    }

    with link = "line.dk.KHP" {
        with layer = -2 track(kh[:nor + 0.49sw, :ryp.yk - 1seg]);
        with layer = -2 track(:station, kh[:ryp.yk - 1.01seg, :ryp.yk]);
    }
}

